#nullable enable

using System;
using System.Threading;
using System.Threading.Tasks;
using Campground.Shared.Network;
using Campground.Shared.Registry;

namespace Campground.Shared.Contracts
{
    /// <summary>HTTPS readiness levels.</summary>
    internal enum HttpsState
    {
        /// <summary>Jellyfin itself serves HTTPS, or a trusted proxy reports https.</summary>
        Ready,

        /// <summary>A proxy is in front, but it isn't trusted (Known proxies), so we can't tell.</summary>
        Unverified,

        /// <summary>Plain http. Browsers hide controllers, keyboard lock and more from the page.</summary>
        NotConfigured,
    }

    /// <summary>The HTTPS answer for one request, with a fix if one is offered.</summary>
    internal sealed record HttpsReadiness(HttpsState State, string Detail, bool FixAvailable, string? FixProvider);

    /// <summary>Arguments of <c>provision</c>.</summary>
    internal sealed record HttpsProvisionRequest(string RequestedBy, string? Hostname);

    /// <summary>Result of <c>provision</c>.</summary>
    internal sealed record HttpsProvisionResult(bool Started, string Message, string? FollowUpUrl);

    /// <summary>
    /// <c>campground.https.v1</c> — one shared HTTPS check, plus a fix offered by Trailhead.
    /// GameTent requires HTTPS; other plugins show it in their setup checks.
    /// </summary>
    internal static class HttpsClient
    {
        internal const string ProvisionOp = "provision";

        /// <summary>Evaluates readiness for a request (pure; feed it the request facts).</summary>
        internal static HttpsReadiness Evaluate(bool requestIsHttps, Classification classification, NetworkSettings settings)
        {
            var fix = Capabilities.ProviderOf(CapabilityNames.Https);
            if (requestIsHttps || classification.ForwardedProtoHttps)
            {
                return new HttpsReadiness(HttpsState.Ready, "Served over HTTPS.", false, null);
            }

            if (classification.ViaProxy && !classification.ProxyTrusted)
            {
                return new HttpsReadiness(
                    HttpsState.Unverified,
                    "A proxy is in front of Jellyfin but isn't listed under Known proxies, so the original scheme can't be read.",
                    fix != null,
                    fix);
            }

            var detail = settings.EnableHttps
                ? "HTTPS is enabled in Jellyfin, but this page was loaded over plain http."
                : "Jellyfin is served over plain http.";
            return new HttpsReadiness(HttpsState.NotConfigured, detail, fix != null, fix);
        }

        /// <summary>Asks Trailhead to set up HTTPS. Null when Trailhead isn't installed.</summary>
        internal static Task<HttpsProvisionResult?> ProvisionAsync(HttpsProvisionRequest request, CancellationToken ct = default)
            => Capabilities.TryInvokeAsync<HttpsProvisionResult>(
                CapabilityNames.Https, ProvisionOp, request, timeout: TimeSpan.FromSeconds(10), ct: ct);

        /// <summary>For the provider (Trailhead).</summary>
        internal static void Provide(string pluginId, int minor, Func<HttpsProvisionRequest, CancellationToken, Task<HttpsProvisionResult>> provision)
            => Capabilities.Provide(CapabilityNames.Https, pluginId, minor, new CapabilityHost().On(ProvisionOp, provision).Build());
    }
}
